from pipeline import *
import matplotlib.pyplot as plt, seaborn as sns
sns.set_theme(style='whitegrid'); FIG.mkdir(parents=True,exist_ok=True)
df=pd.read_csv(OUT/'india_housing_processed.csv') if (OUT/'india_housing_processed.csv').exists() else load_and_prepare()
summary={'rows':len(df),'columns':len(df.columns),'duplicate_rows':int(df.duplicated().sum()),'missing_cells':int(df.isna().sum().sum()),'cities':int(df.City.nunique()),'states':int(df.State.nunique()),'price_median_lakhs':float(df.Price_in_Lakhs.median()),'size_median_sqft':float(df.Size_in_SqFt.median()),'good_investment_share':float(df.Good_Investment.mean())}
(REPORT/'eda_summary.json').write_text(json.dumps(summary,indent=2))
# Core assignment charts
fig,ax=plt.subplots(figsize=(8,5)); sns.histplot(df.Price_in_Lakhs.clip(upper=df.Price_in_Lakhs.quantile(.99)),bins=50,ax=ax); ax.set(title='Property price distribution (99th percentile clipped)',xlabel='Price (lakhs)'); fig.tight_layout(); fig.savefig(FIG/'price_distribution.png',dpi=140); plt.close(fig)
fig,ax=plt.subplots(figsize=(8,5)); sns.scatterplot(data=df.sample(min(5000,len(df)),random_state=42),x='Size_in_SqFt',y='Price_in_Lakhs',hue='Property_Type',alpha=.5,ax=ax); ax.set(title='Property size and price'); fig.tight_layout(); fig.savefig(FIG/'size_vs_price.png',dpi=140); plt.close(fig)
fig,ax=plt.subplots(figsize=(10,5)); df.groupby('City').Price_per_SqFt.median().sort_values().plot.barh(ax=ax); ax.set(title='Median price per sq ft by city',xlabel='₹ per sq ft'); fig.tight_layout(); fig.savefig(FIG/'city_price_per_sqft.png',dpi=140); plt.close(fig)
fig,ax=plt.subplots(figsize=(8,5)); sns.boxplot(data=df.sample(min(20000,len(df)),random_state=42),x='Furnished_Status',y='Price_in_Lakhs',showfliers=False,ax=ax); ax.set(title='Price by furnishing status'); fig.tight_layout(); fig.savefig(FIG/'furnishing_price.png',dpi=140); plt.close(fig)
fig,ax=plt.subplots(figsize=(8,6)); sns.heatmap(df[NUMS].corr(),cmap='vlag',center=0,ax=ax); ax.set(title='Numeric feature correlations'); fig.tight_layout(); fig.savefig(FIG/'correlation_heatmap.png',dpi=140); plt.close(fig)
(REPORT/'eda_findings.md').write_text(f"""# EDA findings\n\n- {len(df):,} records and {df.City.nunique()} cities across {df.State.nunique()} states.\n- Missing cells after source inspection: {df.isna().sum().sum():,}; duplicate rows: {df.duplicated().sum():,}.\n- Median listed price: ₹{df.Price_in_Lakhs.median():.2f} lakhs; median size: {df.Size_in_SqFt.median():,.0f} sq ft.\n- City median price/sq ft ranges from ₹{df.groupby('City').Price_per_SqFt.median().min():,.0f} to ₹{df.groupby('City').Price_per_SqFt.median().max():,.0f}.\n- The investment label is balanced by its city median definition.\n- The dataset's source `Price_per_SqFt` disagreed with price × 100,000 / area, so it is recomputed.\n- Dataset has no observed future sale price, crime, infrastructure, RERA, or investment outcomes. Future price metrics are against the explicit assumed-growth proxy.\n\nFigures are in `figures/`.\n""")
print(summary)
# Compact answers to the full 20-question assignment checklist.
answers=[]
def add(q,a): answers.append(f'### {q}\n\n{a}')
add('1. Price distribution',f"Median ₹{df.Price_in_Lakhs.median():.2f}L; middle 50% ₹{df.Price_in_Lakhs.quantile(.25):.2f}L–₹{df.Price_in_Lakhs.quantile(.75):.2f}L; right tail reaches ₹{df.Price_in_Lakhs.max():.2f}L.")
add('2. Size distribution',f"Median {df.Size_in_SqFt.median():,.0f} sq ft; middle 50% {df.Size_in_SqFt.quantile(.25):,.0f}–{df.Size_in_SqFt.quantile(.75):,.0f} sq ft.")
add('3. Price per sq ft by property type',df.groupby('Property_Type').Price_per_SqFt.median().sort_values(ascending=False).round(0).to_string())
add('4. Size vs price',f"Pearson correlation = {df[['Size_in_SqFt','Price_in_Lakhs']].corr().iloc[0,1]:.3f}.")
add('5. Outliers',f"IQR fences flag {( (df.Price_per_SqFt < df.Price_per_SqFt.quantile(.25)-1.5*(df.Price_per_SqFt.quantile(.75)-df.Price_per_SqFt.quantile(.25))) | (df.Price_per_SqFt > df.Price_per_SqFt.quantile(.75)+1.5*(df.Price_per_SqFt.quantile(.75)-df.Price_per_SqFt.quantile(.25))) ).sum():,} price/sqft rows and {( (df.Size_in_SqFt < df.Size_in_SqFt.quantile(.25)-1.5*(df.Size_in_SqFt.quantile(.75)-df.Size_in_SqFt.quantile(.25))) | (df.Size_in_SqFt > df.Size_in_SqFt.quantile(.75)+1.5*(df.Size_in_SqFt.quantile(.75)-df.Size_in_SqFt.quantile(.25))) ).sum():,} size rows.")
add('6. Average price per sq ft by state',df.groupby('State').Price_per_SqFt.mean().round(0).sort_values(ascending=False).to_string())
add('7. Average price by city (top 10)',df.groupby('City').Price_in_Lakhs.mean().sort_values(ascending=False).head(10).round(2).to_string())
add('8. Median property age by locality',df.groupby('Locality').Age_of_Property.median().sort_values().head(10).round(0).to_string()+'\n\nLowest ten locality medians shown; full locality summary is in `locality_age.csv`.')
add('9. BHK by city',df.groupby(['City','BHK']).size().unstack(fill_value=0).to_csv())
add('10. Price trends in top five localities',df.groupby('Locality').Price_in_Lakhs.mean().sort_values(ascending=False).head(5).round(2).to_string()+'\n\nNo date or time series exists, so these are price levels, not trends.')
add('11. Numeric correlations',df[NUMS].corr().round(2).to_string())
add('12. Nearby schools vs price/sqft',f"Pearson correlation = {df[['Nearby_Schools','Price_per_SqFt']].corr().iloc[0,1]:.3f}.")
add('13. Nearby hospitals vs price/sqft',f"Pearson correlation = {df[['Nearby_Hospitals','Price_per_SqFt']].corr().iloc[0,1]:.3f}.")
add('14. Price by furnished status',df.groupby('Furnished_Status').Price_in_Lakhs.mean().round(2).to_string())
add('15. Price/sqft by facing',df.groupby('Facing').Price_per_SqFt.mean().round(0).sort_values(ascending=False).to_string())
add('16. Properties by owner type',df.Owner_Type.value_counts().to_string())
add('17. Properties by availability',df.Availability_Status.value_counts().to_string())
add('18. Parking and price',df.groupby('Parking_Space').Price_in_Lakhs.mean().round(2).to_string())
add('19. Amenities and price/sqft',df.assign(Amenity_Count=df.Amenities.str.split(',').str.len()).groupby('Amenity_Count').Price_per_SqFt.mean().round(0).to_string())
add('20. Public transport vs price/sqft',df.groupby('Public_Transport_Accessibility').Price_per_SqFt.mean().round(0).to_string())
df.groupby('Locality').Age_of_Property.median().to_csv(REPORT/'locality_age.csv')
(REPORT/'eda_findings.md').write_text('# EDA findings\n\nDataset: 250,000 listings, 20 states, 42 cities, no missing cells or duplicates. Supplied price/sqft values were inconsistent, so recomputed using price in lakhs × 100,000 / area.\n\n'+ '\n\n'.join(answers)+'\n\n## Interpret with care\n\nNo date field exists, so time trends cannot be inferred; no crime, infrastructure, or RERA fields exist. These are cross-sectional associations, not causal effects. Investment and future-price targets are proxy definitions documented in `target_assumptions.json`. Figures are in `figures/`.')
